    },
    {
      "assumption": "정지 시작 시각 기록과 회피 플래그가 복잡한 상황을 잘 처리함",
      "holds": false,
      "why": "상태 전환 지연과 조건 깜빡임이 오히려 정지 타이밍을 흐리게 하여 충돌로 직결됨."
    }
  ],
  "approach_families": [
    {
      "family": "이진 정지/재개 상태머신",
      "turns": "2,4,6,7,9,10,13",
